uses.snippet:
SELECT product_id
FROM Products
WHERE low_fats = 'Y' AND recyclable = 'Y';

SELECT   name
FROM Customer
WHERE referee_id IS NULL OR   referee_id <> 2;

SELECT name, population, area
FROM World
WHERE area >= 3000000 OR population >= 25000000;

SELECT tweet_id
FROM Tweets
WHERE CHAR_LENGTH(content)   > 15;

SELECT p.project_id, ROUND(AVG(e.experience_years), 2) AS average_years
FROM Project p LEFT JOIN Employee e ON p.employee_id = e.employee_id
GROUP BY p.project_id;

SELECT query_name, ROUND(AVG(rating / position), 2) AS quality,
       ROUND(100.0 * AVG(CASE WHEN rating < 3 THEN 1 ELSE 0 END), 2) AS poor_query_percentage
FROM Queries GROUP BY query_name;

SELECT s.product_id, s.year AS first_year, s.quantity, s.price
FROM Sales s JOIN (SELECT product_id, MIN(year) AS first_year FROM Sales GROUP BY product_id) f
ON s.product_id = f.product_id AND s.year = f.first_year;

SELECT MAX(num) AS num FROM (
    SELECT num FROM MyNumbers GROUP BY num HAVING COUNT(*) = 1
) singles;

WITH counted AS (
    SELECT *, COUNT(*) OVER (PARTITION BY employee_id) AS n_departments FROM Employee
)
SELECT employee_id, department_id FROM counted WHERE primary_flag = 'Y' OR n_departments = 1;

SELECT x, y, z,
       CASE WHEN x + y > z AND x + z > y AND y + z > x THEN 'Yes' ELSE 'No' END AS triangle
FROM Triangle;

SELECT sell_date, COUNT(DISTINCT product) AS num_sold,
       GROUP_CONCAT(DISTINCT product ORDER BY product SEPARATOR ',') AS products
FROM Activities GROUP BY sell_date ORDER BY sell_date;

SELECT user_id, name, mail
FROM Users
WHERE REGEXP_LIKE(mail, '^[A-Za-z][A-Za-z0-9_.-]*@leetcode[.]com$', 'c');

SELECT city FROM north_american_cities
WHERE longitude < (SELECT longitude FROM north_american_cities WHERE city = 'Chicago')
ORDER BY longitude;

SELECT m.title, b.domestic_sales, b.international_sales
FROM movies m JOIN boxoffice b ON m.id = b.movie_id
WHERE b.international_sales > b.domestic_sales;

SELECT e.* FROM employees e
WHERE e.salary > (SELECT AVG(d.revenue_generated) FROM employees d
                  WHERE d.department = e.department);
